edits.after:
/*
 * This module parameter is writeable via sysfs, so we can't take
 * system_transition_mutex (which is held during suspend) because
 * suspend itself might be waiting for this lock via module loadoing
 * or similar, leading to A -> B -> A deadlock.
 *
 * Use trylock instead. If we can't get the lock, it means a
 * system transition is in progress, so we shouldn't be changing
 * the compressor anyway.
 */
if (!mutex_trylock(&system_transition_mutex))
	return -EBUSY;

index = sysfs_match_string(comp_alg_enabled, compressor);
if (index >= 0) {
	ret = param_set_copystring(comp_alg_enabled[index], kp);
	if (!ret)
		strscpy(hib_comp_algo, comp_alg_enabled[index],
			sizeof(hib_comp_algo));
} else {
	ret = index;
}

mutex_unlock(&system_transition_mutex);

